 bestScore = sc; best = i; } } if (bestScore - mine < 8) return null; return { dir: k < best ? 'harder' : 'softer', loss: bestScore - mine }; } _readingFit(results) { var f = this._front(results); var a = results.attractiveness, r = results.risk; var high = Math.max(0, a - f.att - 1) + Math.max(0, f.risk - r - 1); var low = Math.max(0, f.att - a - 1) + Math.max(0, r - f.risk - 1); if (high < 1 && low < 1) return null; return { dir: high >= low ? 'optimistic' : 'pessimistic', loss: 20 - this._readingScore(a, r, f) }; } getHint(state, results) { if (!results) return null; var fit = this._stanceFit(results); var rd = this._readingFit(results); if (fit && (!rd || fit.loss >= rd.loss)) return window.mySimulation.t(fit.dir === 'harder' ? 'hint_stance_harder' : 'hint_stance_softer'); if (rd) return window.mySimulation.t(rd.dir === 'optimistic' ? 'hint_read_optimistic' : 'hint_read_pessimistic'); if (results.netScore < 0) return window.mySimulation.t('hint_negative'); if (results.mitigatedRisk >= 6.5) return window.mySimulation.t('hint_high_risk'); if (results.allocation === 0 && this._front(results).risk > 5) return window.mySimulation.t('hint_no_budget'); if (results.netScore > 50) return window.mySimulation.t('hint_strong'); return null; } getHistoryTableConfig() { return [ { key: 'results.dimension', label: 'Dimension', i18nKey: 'col_dimension' }, { key: 'results.attractiveness', label: 'Attract.', i18nKey: 'col_attractiveness' }, { key: 'results.mitigatedRisk', label: 'Risk (Mitig.)', i18nKey: 'col_risk' }, { key: 'results.strategy', label: 'Strategy', i18nKey: 'col_strategy' }, { key: 'results.allocation', label: 'Allocated', i18nKey: 'col_allocation', formatter: function(v) { return '$' + v.toLocaleString(); } }, { key: 'results.reading', label: 'Reading', i18nKey: 'col_reading', formatter: function(v) { return (typeof v === 'number') ? v + '/20' : ''; } }, { key: 'results.netScore', label: 'Net Score', i18nKey: 'col_net_score', formatter: function(v) { return (v >= 